clc; clearvars;
%%
alt_bot = 0;
alt_top = 10e3;
dz = 100;

alt_sim = (alt_bot:dz:alt_top)';
alt_sim_km = alt_sim.*1e-3;

num_bins = length(alt_sim);
%%
glass_db = load("C:\Users\tely1\OneDrive\Desktop\EEJ9903\O3_DIAL_ML\dir\all_glass_profiles.mat").glass_dataset; %[control:filebrowser:2f18]{"position":[17,96]}

glass_files = glass_db.file;
fds = fileDatastore(glass_files, "ReadFcn", @read_glass);
num_files = length(fds.Files);

o3 = NaN(num_bins, 1000);

counter = 1;
for i = 1:num_files
    fdsread = read(fds);
    o3_temp = fdsread.o3;
    alt = fdsread.alt;
    % alt_km = alt .*1e-3;

    n_prof = size(o3_temp,2);

    % o3_filled = fillmissing(o3,"linear","EndValues","previous");
    o3_interp = interp1(alt,o3_temp,alt_sim,"linear",NaN);
    o3_interp = fillmissing(o3_interp,"linear","EndValues","nearest");

    for j = 1:n_prof
        o3(:,counter) = o3_interp(:,j);
        
        counter = counter + 1;
    end
end
%%
% o3(:,id_bad) = [];
idx_subset = randperm(size(o3,2),200);
o3 = o3(:,idx_subset);
%%
addpath(genpath("C:\Users\tely1\OneDrive\Desktop\EEJ9903\signal_analysis\functions")); %[control:filebrowser:030f]{"position":[17,84]}
addpath(genpath("C:\Users\tely1\OneDrive\Desktop\EEJ9903\signal_analysis\overlap_functions")); %[control:filebrowser:947b]{"position":[17,92]}

h = planckConstant;
c = physconst("LightSpeed");

navg = 1200; % Number of laser shots being averaged

lambda_287 = 287.2e-9; % wavelength of light in meters
lambda_299 = 299.1e-9; % wavelength of light in meters

E0_287 = 10.6e-3; % Laser pulse energy in joules
E0_299 = 6.3e-3; % Laser pulse energy in joules

eta_287 = 0.005; % Efficiency factor (excluding quantum efficiency)
eta_299 = 0.0028; % Efficiency factor (excluding quantum efficiency)

etaR = 0.1; % Receiver Efficiency
etaQ = 0.7; % Quantum efficiency

t_r = .2;   % Radius of the receiver in meters
o_r = 0.1;  % Radius of the obstruction
tau = 1/40e6; % sampling length

f = 1.905; % telescope focal length in meters
a = 0.002; % aperture_radius in meters
za = 0; % distance between focal plane and aperture

delta = 0; % distance between receiver and transmitter axes
w0 = 0.0045; % laser beam waist in meters (radius at laser exit)
phi0 = 0.000167; % laser divergence angle (half angle)
phi1 = a/(f+za); % Receiver opening angle/FOV in radians (half angle)
beam_profile = "gaussian"; % Laser beam profile shape

A = pi*(t_r^2 - o_r^2); % Receiver area accounting for obstruction in m^2
Omega = phi1^2 * pi; % Receiver FOV in steradian (phi1 is half angle)

BW = 5e-9; % Interference filter bandwidth in meters (?)

% Ozone absorption cross section dataset
BDM = load("C:\Users\tely1\OneDrive\Desktop\EEJ9903\signal_analysis\cross_sections\ozone\bdm\bdm_287_299.mat"); %[control:filebrowser:3725]{"position":[12,110]}

sigma_o3_287 = BDM.BDM_c287(1) .* 1e-4; % use first temp dependent cross section for now
sigma_o3_299 = BDM.BDM_c299(1) .* 1e-4; % use first temp dependent cross section for now

Nair = airNumberDensity(alt_sim); % Air number density in m^-3

overlap_data = load("C:\Users\tely1\OneDrive\Desktop\EEJ9903\signal_analysis\overlap_data.mat"); % Overlap Function %[control:filebrowser:7543]{"position":[21,95]}
O_interp = interp1(overlap_data.overlap_params_save.alt, overlap_data.O,alt_sim);

BG = load("C:\Users\tely1\OneDrive\Desktop\EEJ9903\signal_analysis\bg_data.mat"); % Background radiance data %[control:filebrowser:950c]{"position":[11,80]}

[NB_287, CB_287] = background(lambda_287,A,tau,etaR,BW,phi1,BG.L_287_avg); % Background counts (photons/bin)
[NB_299, CB_299] = background(lambda_299,A,tau,etaR,BW,phi1,BG.L_299_avg);

NS_287 = signal(alt_sim,lambda_287,E0_287,A,tau,eta_287,etaQ,Nair,sigma_o3_287,o3,O_interp); % Signal counts (photons/bin)
NS_299 = signal(alt_sim,lambda_299,E0_299,A,tau,eta_299,etaQ,Nair,sigma_o3_299,o3,O_interp); 

% C_287 = convert_to_countrate(NS_287,tau); % Count rate in Hz
% C_299 = convert_to_countrate(NS_299,tau);

[~, N_nsy_287] = add_noise(NS_287,NB_287,navg); % Add background signal and poisson noise
[~, N_nsy_299] = add_noise(NS_299,NB_299,navg);

C_nsy_287 = convert_to_countrate(N_nsy_287,tau) .* 1e-6;
C_nsy_299 = convert_to_countrate(N_nsy_299,tau) .* 1e-6;
%%
num_channels = 2;
num_batch = size(N_nsy_287,2);

signals = NaN(num_bins,1,num_channels,num_batch);
for i = 1:num_batch
    signals(:,:,1,i) = C_nsy_287(:,i);
    signals(:,:,2,i) = C_nsy_299(:,i);
end

% test = all(squeeze(signals(:,:,1,:)) == N_nsy_287,"all")
% test2 = all(squeeze(signals(:,:,2,:)) == N_nsy_299,"all")

[idx_train,idx_validation, idx_test] = trainingPartitions(num_batch,[.85, .1, .05]);

signals_train = signals(:,:,:,idx_train);
signals_validation = signals(:,:,:,idx_validation);
signals_test = signals(:,:,:,idx_test);

o3_train = o3(:,idx_train);
o3_validation = o3(:,idx_validation)';
o3_test = o3(:,idx_test)';
%%
load("C:\Users\tely1\OneDrive\Desktop\EEJ9903\O3_DIAL_ML\dir\net_101.mat"); %[control:filebrowser:453d]{"position":[6,74]}

% create net programmatically based on input size
% remove poor ozone profiles from the beginning. start with ones that don't
% have many genuine points

num_epochs = 5000;

options = trainingOptions("sgdm", ...
    MaxEpochs=num_epochs, ...
    Verbose=false, ...
    Plots="training-progress",...
    InitialLearnRate=.01, NormalizeTargets=true);

options.ValidationData = {signals_validation, o3_validation};
options.ValidationPatience = 50;

nettrained = trainnet(signals_train,o3_train',net,"mse", options); %[output:754cf8d6]
%%
Y = predict(nettrained,signals)';

r = err(Y,o3);

t = 2e35;
id_bad = find(r>=t);
n_bad = length(id_bad);

%%
figure; %[output:1c46dbd3]
plot(r) %[output:1c46dbd3]
hold on %[output:1c46dbd3]
scatter(id_bad, r(id_bad)) %[output:1c46dbd3]
hold off %[output:1c46dbd3]
%%
id = 2; %[control:slider:4c8e]{"position":[6,7]}
figure
plot(o3(:,id_bad(id)),alt_sim_km) %[output:0975289b]
title(num2str(id_bad(id)))

function error = err(Ypred,Ytrue)
    error = (Ypred - Ytrue).^2;
    error = squeeze(mean(error,1));
end
%%
if false==true %[control:checkbox:725d]{"position":[4,9]}
c_lim = [0 2e18];
y_lim = [alt_bot alt_top] .* 1e-3;

id = 1;

figure;
plot(o3_interp(:,id),alt_sim_km)
hold on
plot(o3_filled(:,id),alt_km)
plot(o3(:,id),alt_km)
hold off
figure;
i = imagesc(1:n_prof,alt_km,o3);
colorbar
set(gca, 'YDir','normal')
i.AlphaData = ~isnan(o3);
ylim(y_lim)
clim(c_lim)
figure;
i = imagesc(1:n_prof,alt_km,o3_filled);
colorbar
set(gca, 'YDir','normal')
i.AlphaData = ~isnan(o3_filled);
ylim(y_lim)
clim(c_lim)
figure;
i = imagesc(1:n_prof,alt_sim_km,o3_interp);
colorbar
set(gca, 'YDir','normal')
i.AlphaData = ~isnan(o3_interp);
ylim(y_lim)
clim(c_lim)
end
%%
id = 1;
c_lim = [0 2e18];
y_lim = [alt_bot alt_top] .* 1e-3;

if false==true %[control:checkbox:93ed]{"position":[4,9]}
    figure;
    img = imagesc(1:n_prof,alt_sim_km,o3);
    colorbar
    set(gca, 'YDir','normal')
    img.AlphaData = ~isnan(o3);
    ylim(y_lim)
    clim(c_lim)

    figure;
    img = imagesc(1:n_prof,alt_sim_km,log10(N_nsy_287));
    colorbar
    set(gca, 'YDir','normal')
    img.AlphaData = ~isnan(N_nsy_287);
    ylim(y_lim)
    % clim(c_lim)

    figure;
    img = imagesc(1:n_prof,alt_sim_km,log10(N_nsy_299));
    colorbar
    set(gca, 'YDir','normal')
    img.AlphaData = ~isnan(N_nsy_299);
    ylim(y_lim)
    % clim(c_lim)

    figure;
    semilogy(alt_sim_km,N_nsy_287(:,id),'DisplayName','287 nm')
    hold on
    plot(alt_sim_km,N_nsy_299(:,id),'DisplayName','299 nm')
    hold off
    grid on
    legend
end
%%
function result = read_glass(file)
    o3 = double(hdfread(file,"O3.NUMBER.DENSITY_ABSORPTION.DIFFERENTIAL"));
    alt = double(hdfread(file,"ALTITUDE"));

    o3(o3<0) = NaN;

    result.o3 = o3';
    result.alt = alt';
end

